using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Threading.Tasks;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
namespace SpatialWallpaper.Supervision.Preview {
 // Explicit preview simulation, never an external model. Owns every accepted
 // socket and handler until Completion, including idle and cancelled requests.
 public sealed class DeterministicLlmServer:IDisposable {
  readonly object gate=new object();readonly TcpListener listener;readonly CancellationTokenSource cancel=new CancellationTokenSource();readonly HashSet<TcpClient> clients=new HashSet<TcpClient>();readonly HashSet<Task> handlers=new HashSet<Task>();readonly Task accepting;readonly TaskCompletionSource<bool> completion=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
  readonly string credential=Guid.NewGuid().ToString("N")+Guid.NewGuid().ToString("N");readonly Uri endpoint;const string Model="spatialwallpaper-deterministic-simulation-v1";volatile bool closed;Exception handlerFailure;int accepted,disposed;
  public Task Completion=>completion.Task;public bool ResourcesReleased=>completion.Task.Status==TaskStatus.RanToCompletion;public int AcceptedRequests=>Volatile.Read(ref accepted);
  public JObject Configuration=>new JObject{{"endpoint",endpoint.AbsoluteUri},{"model",Model},{"credential",credential}};
  public DeterministicLlmServer(){listener=new TcpListener(IPAddress.Loopback,0);listener.Start(8);endpoint=new Uri("http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/v1/chat/completions");accepting=Accept();}
  async Task Accept(){try{while(true){var client=await listener.AcceptTcpClientAsync().ConfigureAwait(false);lock(gate){if(closed){client.Dispose();return;}if(clients.Count>=8){client.Dispose();continue;}client.ReceiveTimeout=200;client.SendTimeout=500;var stream=client.GetStream();clients.Add(client);var task=Task.Run(()=>Serve(client,stream));handlers.Add(task);_ = task.ContinueWith(done=>{lock(gate){if(done.IsFaulted&&handlerFailure==null)handlerFailure=done.Exception.GetBaseException();handlers.Remove(done);}},CancellationToken.None,TaskContinuationOptions.ExecuteSynchronously,TaskScheduler.Default);}}}catch(Exception error)when(closed&&(error is SocketException||error is ObjectDisposedException||error is InvalidOperationException)){} }
  int Read(NetworkStream stream,byte[] bytes,int offset,int count,Stopwatch deadline){while(true){cancel.Token.ThrowIfCancellationRequested();if(deadline.ElapsedMilliseconds>5000)throw new TimeoutException("mock-request-deadline");try{return stream.Read(bytes,offset,count);}catch(IOException error)when(error.InnerException is SocketException socket&&(socket.SocketErrorCode==SocketError.TimedOut||socket.SocketErrorCode==SocketError.WouldBlock)){}}}
  static void Reply(NetworkStream stream,int code,string body){byte[] bytes=Encoding.UTF8.GetBytes(body),head=Encoding.ASCII.GetBytes("HTTP/1.1 "+code+" "+(code==200?"OK":code==401?"Unauthorized":"Bad Request")+"\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(bytes,0,bytes.Length);}
  void Serve(TcpClient client,NetworkStream ownedStream){try{using(var stream=ownedStream)try{
   var deadline=Stopwatch.StartNew();var header=new List<byte>();var one=new byte[1];while(true){if(header.Count>=8192)throw new InvalidDataException("mock-header-size");if(Read(stream,one,0,1,deadline)!=1)throw new EndOfStreamException();byte value=one[0];if(value>127||value<32&&value!=13&&value!=10&&value!=9)throw new InvalidDataException("mock-header-encoding");header.Add(value);int count=header.Count;if(count>=4&&header[count-4]==13&&header[count-3]==10&&header[count-2]==13&&header[count-1]==10)break;}
   string[] lines=Encoding.ASCII.GetString(header.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);if(lines[0]!="POST /v1/chat/completions HTTP/1.1")throw new InvalidDataException("mock-request-line");var fields=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in lines.Skip(1).Where(line=>line.Length>0)){int colon=line.IndexOf(':');if(colon<1||fields.Count>=32||line.Substring(0,colon).Any(c=>!(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='-')))throw new InvalidDataException("mock-header-fields");if(fields.ContainsKey(line.Substring(0,colon)))throw new InvalidDataException("mock-header-duplicate");fields.Add(line.Substring(0,colon),line.Substring(colon+1).Trim());}
   if(!fields.TryGetValue("Content-Length",out var length)||!int.TryParse(length,NumberStyles.None,CultureInfo.InvariantCulture,out int size)||size<1||size>32768||fields.ContainsKey("Transfer-Encoding"))throw new InvalidDataException("mock-body-bound");
   if(!fields.TryGetValue("Authorization",out var authorization)||authorization!="Bearer "+credential){Reply(stream,401,"{}");return;}if(!fields.TryGetValue("Content-Type",out var contentType)||!string.Equals(contentType.Split(';')[0].Trim(),"application/json",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("mock-content-type");
   if(fields.TryGetValue("Expect",out var expectation)){if(!string.Equals(expectation,"100-continue",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("mock-expectation");byte[] ready=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");stream.Write(ready,0,ready.Length);}
   var body=new byte[size];for(int offset=0;offset<size;){int count=Read(stream,body,offset,size-offset,deadline);if(count==0)throw new EndOfStreamException();offset+=count;}JObject request;using(var input=new StringReader(new UTF8Encoding(false,true).GetString(body)))using(var reader=new JsonTextReader(input){MaxDepth=8,DateParseHandling=DateParseHandling.None}){request=JObject.Load(reader,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(reader.Read())throw new InvalidDataException("mock-json-tail");}
   if(request.Count!=4||request["model"]?.Type!=JTokenType.String||(string)request["model"]!=Model||request["stream"]?.Type!=JTokenType.Boolean||(bool)request["stream"]||request["max_tokens"]?.Type!=JTokenType.Integer||(int)request["max_tokens"]!=1024||!(request["messages"] is JArray messages)||messages.Count!=1||!(messages[0] is JObject message)||message.Count!=2||message["role"]?.Type!=JTokenType.String||(string)message["role"]!="user"||message["content"]?.Type!=JTokenType.String||((string)message["content"]).Length>4096)throw new InvalidDataException("mock-json-contract");
   Interlocked.Increment(ref accepted);Task.Delay((string)message["content"]=="hold"?5000:100,cancel.Token).GetAwaiter().GetResult();Reply(stream,200,"{\"choices\":[{\"message\":{\"content\":\"reply-as-data\"}}]}");
  }catch(Exception error)when(error is InvalidDataException||error is JsonException||error is DecoderFallbackException||error is OverflowException){try{Reply(stream,400,"{}");}catch(IOException){}catch(ObjectDisposedException){}}}
  catch(Exception error)when(error is IOException||error is SocketException||error is ObjectDisposedException||error is OperationCanceledException||error is TimeoutException){}
  finally{client.Dispose();lock(gate)clients.Remove(client);}}
  async Task FinishStop(){try{await accepting.ConfigureAwait(false);Task[] pending;lock(gate)pending=handlers.ToArray();await Task.WhenAll(pending).ConfigureAwait(false);lock(gate){if(handlerFailure!=null)throw new InvalidOperationException("mock-handler-failed",handlerFailure);}completion.TrySetResult(true);}catch(Exception error){completion.TrySetException(error);}}
  public void Dispose(){TcpClient[] pending=null;lock(gate){if(!closed){closed=true;pending=clients.ToArray();}}if(pending!=null){cancel.Cancel();listener.Stop();foreach(var client in pending)client.Dispose();_ = FinishStop();}if(!completion.Task.Wait(1500))throw new TimeoutException("mock-owned-resources-cleanup-deadline");completion.Task.GetAwaiter().GetResult();if(Interlocked.Exchange(ref disposed,1)==0)cancel.Dispose();}
 }
}
